# Generates schema-prod.sql from the live schema dump (supabase/live-capture/baseline/schema.sql, run 38015733264, 10 Oct 2026) for the
# relations this fixture holds. Usage: python3 -I gen-schema.py <schema.sql> <out.sql>. schema-live-patch.sql then brings it to 5 Nov 2026.
import json,re,sys
def split_sql(s):
    out=[]; i=0; n=len(s); start=0; q=None; dq=None
    while i<n:
        c=s[i]
        if dq:
            if s.startswith(dq,i): i+=len(dq); dq=None; continue
            i+=1; continue
        if q:
            if c==q:
                if i+1<n and s[i+1]==q: i+=2; continue
                q=None
            i+=1; continue
        if c=="'" : q="'"; i+=1; continue
        if c=='"': q='"'; i+=1; continue
        if c=='-' and s.startswith('--',i):
            j=s.find('\n',i); i = n if j<0 else j; continue
        if c=='$':
            m=re.match(r'\$[A-Za-z_0-9]*\$', s[i:])
            if m: dq=m.group(0); i+=len(dq); continue
        if c==';':
            out.append(s[start:i+1].strip()); start=i+1
        i+=1
    if s[start:].strip(): out.append(s[start:].strip())
    return out
stmts=split_sql(open(sys.argv[1]).read())
T1=['catalogue.providers','catalogue.courses','catalogue.campuses','catalogue.course_campuses','ref.countries','ref.subdivisions','pipeline.campus_regional_class','search.course_documents','pipeline.layer4_block_decisions','scholarship.scholarships','scholarship.criteria','scholarship.nationality_readings','scholarship.course_mappings','pipeline.layer4_review_items','pipeline.scholarship_ai_reviews','pipeline.platform_toolset_settings','catalogue.provider_assets','scholarship.award_tiers','scholarship.course_financial_calculations','catalogue.provider_collection_memberships','ref.institution_collections','ranking.observation_provider_links','ranking.observations','ranking.editions','ranking.systems']
T2=['ranking.publisher_institutions','catalogue.course_fees','pipeline.evidence_artifacts','pipeline.sources','pim.entity_registry','ref.fields_of_study','ref.study_levels','ref.provider_types','pipeline.layer3_interpretations','pipeline.platform_toolsets','ref.currencies','ref.regions','scholarship.scopes','scholarship.criterion_groups','scholarship.offering_cycles']
V=['security.layer4_search_blocked_scholarships','security.layer4_active_blocks','security.layer4_search_blocked_courses','security.layer4_search_blocked_providers']
ALL=T1+T2
q=lambda t: '"%s"."%s"'%tuple(t.split('.'))
def tbl_of(s):
    m=re.match(r'^(?:CREATE TABLE IF NOT EXISTS|ALTER TABLE (?:ONLY )?|CREATE (?:UNIQUE )?INDEX "[^"]+" ON (?:ONLY )?|GRANT [A-Z ,]+ ON TABLE |REVOKE [A-Z ,]+ ON TABLE |CREATE POLICY "[^"]+" ON |COMMENT ON (?:TABLE|VIEW) |CREATE OR REPLACE VIEW )\s*("[^"]+"\."[^"]+")', s)
    if m: return m.group(1).replace('"','')
    m=re.match(r'^CREATE OR REPLACE TRIGGER "[^"]+" .*? ON ("[^"]+"\."[^"]+") ', s, re.S)
    if m: return m.group(1).replace('"','')
    return None
out={'table':[],'seq':[],'cons':[],'fk':[],'omit':[],'idx':[],'trg':[],'rls':[],'grant':[],'view':[],'comment':[],'trgfn':set()}
seqs=set()
for s in stmts:
    m=re.match(r'^ALTER SEQUENCE ("[^"]+"\."[^"]+") OWNED BY ("[^"]+"\."[^"]+")\.', s)
    if m and m.group(2).replace('"','') in ALL: seqs.add(m.group(1))
for s in stmts:
    if any(s.startswith(p+sq) for sq in seqs for p in ('CREATE SEQUENCE IF NOT EXISTS ','ALTER SEQUENCE ')) : out['seq'].append(s); continue
    t=tbl_of(s)
    if t is None: continue
    if t in V:
        if s.startswith('CREATE OR REPLACE VIEW'): out['view'].append(s)
        elif s.startswith('GRANT') or s.startswith('REVOKE'): out['grant'].append(s)
        continue
    if t not in ALL: continue
    lvl1 = t in T1
    if s.startswith('CREATE TABLE'): out['table'].append(s)
    elif s.startswith('ALTER TABLE') and 'OWNER TO' in s: pass
    elif 'FOREIGN KEY' in s:
        tgt=re.search(r'REFERENCES ("[^"]+"\."[^"]+")',s).group(1).replace('"','')
        (out['fk'] if tgt in ALL else out['omit']).append(s)
    elif 'ADD CONSTRAINT' in s: out['cons'].append(s)
    elif 'SET DEFAULT "nextval"' in s: out['seq'].append(s)
    elif 'ROW LEVEL SECURITY' in s: out['rls'].append(s)
    elif s.startswith('CREATE') and 'INDEX' in s.split('(')[0]: out['idx'].append(s)
    elif s.startswith('CREATE OR REPLACE TRIGGER'):
        out['trg'].append(s); out['trgfn'].add(re.search(r'EXECUTE FUNCTION (\S+?)\(',s).group(1))
    elif s.startswith('GRANT') or s.startswith('REVOKE'): out['grant'].append(s)
    elif s.startswith('COMMENT'): out['comment'].append(s)
    else: print('UNHANDLED', s[:120], file=sys.stderr)
print(json.dumps({k:len(v) for k,v in out.items()}), file=sys.stderr)
missing=[t for t in ALL if not any(s.startswith('CREATE TABLE IF NOT EXISTS '+q(t)+' ') for s in out['table'])]
print('missing tables', missing, file=sys.stderr)
W=open(sys.argv[2],'w')
W.write('-- GENERATED by gen.py from supabase/live-capture/baseline/schema.sql (live dump of 10 Oct 2026); then patched to live 5 Nov 2026 by schema-live-patch.sql\n')
for k in ['seq','table','cons','fk','idx']:
    W.write('\n-- '+k+'\n'); [W.write(s+'\n') for s in out[k]]
W.write('\n-- trigger functions: not reproduced (they act on writes; the change under test only reads). Same names, no-op bodies.\n')
for f in sorted(out['trgfn']): W.write('CREATE OR REPLACE FUNCTION %s() RETURNS trigger LANGUAGE plpgsql AS $t$ begin if tg_op = \'DELETE\' then return old; end if; return new; end $t$;\n' % f)
for k in ['trg','rls','view','grant','comment']:
    W.write('\n-- '+k+'\n'); [W.write(s+'\n') for s in out[k]]
W.write('\n-- foreign keys to tables outside the fixture (not created; listed for the record)\n')
for s in out['omit']: W.write('-- '+s.replace('\n',' ')+'\n')
print('omitted FK targets', sorted(set(re.search(r'REFERENCES ("[^"]+"\."[^"]+")',s).group(1) for s in out['omit'])), file=sys.stderr)
